{"code": "import glob
import os
train_dir="data/signature-verification-dataset/sign_data/train"
for per in os.listdir(train_dir):
    if 'forg' in per.lower():
        files = glob.glob(train_dir+'/'+per+'/*.*')
        if files:
            with open(files[0], 'rb') as f:
                header = f.read(16)
                print(f"File: {os.path.basename(files[0])}")
                print(f"First 16 bytes (hex): {header.hex()}")
                print(f"First 16 bytes: {header}")
            break"}

